/** * freq_pwm=(Freq_MCU/(N*256)) * en is prescelar scale and it must be = 1,8,64,256,1024 *  * if you want 62500 Hz output  * 16000000/N*256=62500 * so N=1 Output:62500Hz *    N=8 Output:7812Hz *  * i am going to try to drive a IR led  * and watch with my phone camera how it is working. */#define F_CPU 16000000UL#include<avr\io.h>#include<util/delay.h>#include<stdlib.h>#define GPIO_PIN_0 0b00000001#define GPIO_PIN_1 0b00000010#define GPIO_PIN_2 0b00000100#define GPIO_PIN_3 0b00001000#define GPIO_PIN_4 0b00010000#define GPIO_PIN_5 0b00100000#define GPIO_PIN_6 0b01000000#define GPIO_PIN_7 0b10000000#define GPIO_PIN_ALL 0b11111111void GPIO_init(){    DDRD|=GPIO_PIN_6|GPIO_PIN_5;}void PWM_Init(){    //Fast PWM Mod (WGM01 = 1, WGM00 = 1)    //Non-Inverting PWM selection (COM0A1 = 1): if Counter catch the OCR0A set the pin_low     TCCR0A = (1 << COM0A1) | (1 << WGM01) | (1 << WGM00);        /*     *********Read the DataSheet or ask to AI            CS02	CS01	CS00	DESCRIPTION                0	0	0	Timer/Counter0 Disabled                0	0	1	No Prescaling                0	1	0	Clock / 8                0	1	1	Clock / 64                1	0	0	Clock / 256                1	0	1	Clock / 1024     */        //Clock Prescaler = 64 selection (CS01 = 1, CS00 = 1)    // Frekans: 16.000.000 / (64 * 256) ? 976.5 Hz    TCCR0B = (1 << CS01) | (1 << CS00);    // Dutsy Cycle start with 0 = %0    OCR0A = 0;}void PWM_Set_Duty(uint8_t duty) //let set duty{    // 0: always LOW (%0 )    // 255: always HIGH (%100 )    OCR0A = duty;}void Delay_ms_(int param_delay){    while(param_delay>0)    {        param_delay--;    _delay_ms(1);    }}//this is other thingvoid Cave_things_PWM(uint8_t parameter_duty_cycle, int parameter_Hz){    int this_Hz=1000/parameter_Hz;        int this_duty_cycle_High=0;    int this_duty_cycle_Low=0;        this_duty_cycle_High=parameter_duty_cycle;    this_duty_cycle_Low=abs(this_Hz-parameter_duty_cycle);        PORTB|=GPIO_PIN_5;    Delay_ms_(this_duty_cycle_High);    PORTB&=~GPIO_PIN_5;    Delay_ms_(this_duty_cycle_Low);            }void main(){    GPIO_init();    PWM_Init();    uint8_t this_duty=0;    while(1)    {        PWM_Set_Duty(this_duty++);        Cave_things_PWM(60, 360);      }}